#include <vector>
#include <omp.h>

/* Compute the reverse prefix (suffix) sum of the vector x into output.
   The result at position i is  sum_{j=i}^{n-1} x[j].
   The implementation works correctly for any number of OpenMP threads.
*/
void reversePrefixSum(const std::vector<int>& x, std::vector<int>& output) {
    const std::size_t n = x.size();
    output.clear();
    output.resize(n);
    if (n == 0) return;

    /* ---------- 1. Parallel exclusive scan (prefix sum) ---------- */
    std::vector<long long> prefix(n);               // temporary prefix sums
    int num_threads = 1;

    // Determine the number of threads that will be used
    #pragma omp parallel
    {
        #pragma omp single
        num_threads = omp_get_num_threads();
    }

    std::vector<long long> thread_sum(num_threads, 0);   // sum of each thread's chunk
    std::vector<long long> offset(num_threads, 0);      // prefix of thread sums

    // Each thread computes a local prefix for its chunk
    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        long long local = 0;

        #pragma omp for schedule(static)
        for (std::size_t i = 0; i < n; ++i) {
            local += static_cast<long long>(x[i]);
            prefix[i] = local;               // local (in‑thread) prefix
        }
        thread_sum[tid] = local;              // total of this thread's chunk
    }

    // Build the offsets (prefix of thread sums)
    for (int t = 1; t < num_threads; ++t) {
        offset[t] = offset[t - 1] + thread_sum[t - 1];
    }

    // Add the proper offset to each element of the local prefix
    #pragma omp parallel for schedule(static)
    for (std::size_t i = 0; i < n; ++i) {
        const int tid = omp_get_thread_num(); // same static schedule as above
        prefix[i] += offset[tid];
    }

    /* ---------- 2. Convert to reverse prefix (suffix) sum ---------- */
    const long long total = prefix[n - 1];   // sum of all elements

    #pragma omp parallel for schedule(static)
    for (std::size_t i = 0; i < n; ++i) {
        long long before = (i == 0) ? 0 : prefix[i - 1];
        output[i] = static_cast<int>(total - before);
    }
}
